-- Transactional live regression: all synthetic rows are rolled back.
BEGIN;
DO $test$
DECLARE
  program_id uuid; saved jsonb; before_schedule jsonb := '[{"day":"Mon","workout":{"name":"Regression test","exercises":[{"name":"Dumbbell Goblet Squat","video_url":"https://plantbased-balance.org/assets/exercise-videos/compat/goblet-squat.mp4","videoUrl":"https://plantbased-balance.org/assets/exercise-videos/compat/goblet-squat.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Dumbbell Bench Press","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/b43812635823cb88b97346e5.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/b43812635823cb88b97346e5.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Dumbbell Single Arm Row","video_url":"https://plantbased-balance.org/assets/exercise-videos/compat/dumbbell-single-arm-row.mp4","videoUrl":"https://plantbased-balance.org/assets/exercise-videos/compat/dumbbell-single-arm-row.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Hollow Body Hold","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/acea1803f9eb80ee594aec44.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/acea1803f9eb80ee594aec44.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Dumbbell Romanian Deadlift","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/8caf3c7873a3dcc4386fb8b4.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/8caf3c7873a3dcc4386fb8b4.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Kneeling Push Up","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/2d2a10f666178ff02067830d.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/2d2a10f666178ff02067830d.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Standing Dumbbell Bicep Curls","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/28b713946443b8d05c9abc23.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/28b713946443b8d05c9abc23.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Plank","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/5d89bdb72cbf41264de67eba.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/5d89bdb72cbf41264de67eba.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Dumbbell Skull Crusher","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/1b120133b95f99d089dff702.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/1b120133b95f99d089dff702.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Ab Crunch","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/87429d2a4602b601301c53e7.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/87429d2a4602b601301c53e7.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Bench Single Leg Hip Thrust","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/086f0bae9d1b94f5938618a7.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/086f0bae9d1b94f5938618a7.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"High Plank Shoulder Taps","video_url":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/d405852b53c360ca99485fe7.mp4","videoUrl":"https://f005.backblazeb2.com/file/plantbasedbalancestories/balance-social/app-exercise-videos/phone-v1/d405852b53c360ca99485fe7.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Cat Cow","video_url":"https://plantbased-balance.org/assets/exercise-videos/compat/cat-cow.mp4","videoUrl":"https://plantbased-balance.org/assets/exercise-videos/compat/cat-cow.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Child''s Pose","video_url":"https://plantbased-balance.org/assets/exercise-videos/compat/childs-pose.mp4","videoUrl":"https://plantbased-balance.org/assets/exercise-videos/compat/childs-pose.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5},{"name":"Yoga - Seated Side Stretch","video_url":"https://plantbased-balance.org/assets/exercise-videos/compat/yoga-seated-side-stretch.mp4","videoUrl":"https://plantbased-balance.org/assets/exercise-videos/compat/yoga-seated-side-stretch.mp4","reps":"12","sets":3,"coachCue":"Keep this cue","prescribedWeightKg":5}]}},{"day":"Tue","workout":{"type":"rest","exercises":[]}}]'::jsonb;
  ex jsonb; untouched uuid; rejected boolean := false;
BEGIN
  INSERT INTO public.custom_workout_programs(user_id,program_name,weekly_schedule,is_active)
  VALUES ('2f67ca67-7566-48d6-b29f-b2d73caa24d4','Video guard regression — rollback',before_schedule,false)
  RETURNING id,weekly_schedule INTO program_id,saved;
  FOR ex IN SELECT value FROM jsonb_array_elements(saved #> '{0,workout,exercises}') LOOP
    IF ex->>'video_url' NOT LIKE 'https://plantbased-balance.org/assets/exercise-videos/%' OR ex->>'video_url' IS DISTINCT FROM ex->>'videoUrl' THEN RAISE EXCEPTION 'Insert retained external or mismatched URL: %',ex; END IF;
  END LOOP;
  IF (SELECT jsonb_agg(e - 'video_url' - 'videoUrl') FROM jsonb_array_elements(saved #> '{0,workout,exercises}') e) IS DISTINCT FROM (SELECT jsonb_agg(e - 'video_url' - 'videoUrl') FROM jsonb_array_elements(before_schedule #> '{0,workout,exercises}') e) THEN RAISE EXCEPTION 'Prescription changed'; END IF;
  IF saved->1 IS DISTINCT FROM before_schedule->1 THEN RAISE EXCEPTION 'Rest day changed'; END IF;
  -- Missing URL resolves from exact verified name; both fields are filled.
  UPDATE public.custom_workout_programs SET weekly_schedule=jsonb_set(before_schedule,'{0,workout,exercises,0}',(before_schedule #> '{0,workout,exercises,0}') - 'video_url' - 'videoUrl') WHERE id=program_id RETURNING weekly_schedule INTO saved;
  IF saved #>> '{0,workout,exercises,0,video_url}' NOT LIKE 'https://plantbased-balance.org/%' THEN RAISE EXCEPTION 'Missing video was not filled'; END IF;
  -- Camel-case-only older programs are also repaired.
  UPDATE public.custom_workout_programs SET weekly_schedule=jsonb_set(before_schedule,'{0,workout,exercises,1}',(before_schedule #> '{0,workout,exercises,1}') - 'video_url') WHERE id=program_id RETURNING weekly_schedule INTO saved;
  IF saved #>> '{0,workout,exercises,1,video_url}' LIKE '%backblaze%' THEN RAISE EXCEPTION 'Camel-only external source survived'; END IF;
  -- A future exercise cannot silently bring back an unverified external host.
  BEGIN
    UPDATE public.custom_workout_programs SET weekly_schedule=jsonb_set(before_schedule,'{0,workout,exercises,0}','{"name":"Future Demo","video_url":"https://example.com/new.mp4"}'::jsonb) WHERE id=program_id;
  EXCEPTION WHEN check_violation THEN rejected := true;
  END;
  IF NOT rejected THEN RAISE EXCEPTION 'Unknown external demo was accepted'; END IF;
  -- Unrelated clients keep their original program behavior.
  INSERT INTO public.custom_workout_programs(user_id,program_name,weekly_schedule,is_active)
  VALUES ('cc632168-874c-447e-a4ad-ee7f6b40bb7e','Video guard unrelated-client regression — rollback',before_schedule,false) RETURNING id,weekly_schedule INTO untouched,saved;
  IF saved IS DISTINCT FROM before_schedule THEN RAISE EXCEPTION 'Unrelated client changed'; END IF;
  RAISE NOTICE 'PASS: insert, update, all 15 demos, prescription preservation, rest days, missing/camel-only URLs, rejected unknown external video, unrelated client isolation';
END;
$test$;
ROLLBACK;
